  background-color: #4caf50;
  color: white;
  padding: 12px 24px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 16px;
  font-weight: 500;
  width: auto;
  display: block;
  margin: 20px;
}

.submitButton:hover {
  background-color: #45a049;
}

.submitButton:disabled {
  background-color: #cccccc;
  cursor: not-allowed;
}

